    "isPartOf": {"@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93320#webpage"},
    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uB9AC\uC0AC\uC774\uD074 \uB2E4\uC6B4\uC774\uB780 \uBB34\uC5C7\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uAE30\uC874 \uC81C\uD488\uC5D0\uC11C \uD68C\uC218\uD55C \uB2E4\uC6B4\uC744 \uB2E4\uC2DC \uCDA9\uC804\uC7AC\uB85C \uD65C\uC6A9\uD55C \uC18C\uC7AC\uC785\uB2C8\uB2E4. \uAC89\uAC10\uC774\uB098 \uC548\uAC10\uC5D0 \uC0AC\uC6A9\uB418\uB294 \uB9AC\uC0AC\uC774\uD074 \uC6D0\uB2E8\uACFC\uB294 \uAD6C\uBD84\uB418\uBA70, \uC81C\uD488\uBCC4 \uC18C\uC7AC \uAD6C\uC131\uACFC \uC801\uC6A9 \uBD80\uC704\uB294 \uC0C1\uD488 \uC0C1\uC138\uC815\uBCF4\uC5D0\uC11C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uBC15\uBCF4\uAC80\uC774 \uCC29\uC6A9\uD55C \uC624\uB80C\uC9C0 \uB215\uC2DC\uB294 \uC5B4\uB5A4 \uC81C\uD488\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB0A8\uC131 1996 \uB808\uD2B8\uB85C \uB215\uC2DC \uC790\uCF13(M'S 1996 RETRO NUPTSE JACKET)\uC785\uB2C8\uB2E4. \uCEEC\uB7EC\uB294 \uC624\uB80C\uC9C0(ORG), \uD488\uBC88\uC740 NJ1DS75F\uC785\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uAE30\uD68D\uC804\uC5D0\uC11C \uD568\uAED8 \uB9CC\uB098\uBCFC \uC218 \uC788\uB294 \uB2E4\uC6B4 \uC790\uCF13\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uBC15\uBCF4\uAC80\uC774 \uCC29\uC6A9\uD55C \uB0A8\uC131 1996 \uB178\uBCA8\uD2F0 \uB215\uC2DC \uC790\uCF13, \uB0A8\uC131 \uB77C\uC774\uD2B8 \uD329 \uB2E4\uC6B4 \uC790\uCF13, \uB0A8\uC131 \uD2B8\uB808\uC77C \uD329 \uB2E4\uC6B4 \uC790\uCF13\uC744 \uD568\uAED8 \uB9CC\uB098\uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAC01 \uC0C1\uD488 \uC0C1\uC138\uD398\uC774\uC9C0\uC5D0\uC11C \uCEEC\uB7EC\uC640 \uC0AC\uC774\uC988\uB97C \uD655\uC778\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uB77C\uC774\uD2B8 \uD329 \uB2E4\uC6B4\uACFC \uD2B8\uB808\uC77C \uD329 \uB2E4\uC6B4\uC740 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB77C\uC774\uD2B8 \uD329 \uB2E4\uC6B4\uC740 \uCD08\uACBD\uB7C9 \uC18C\uC7AC\uC640 \uC554\uD640\u00B7\uC18C\uB9E4\uC758 \uD14C\uC774\uD551 \uB514\uD14C\uC77C\uC774 \uD2B9\uC9D5\uC785\uB2C8\uB2E4. \uD2B8\uB808\uC77C \uD329 \uB2E4\uC6B4\uC740 \uBCFC\uB968\uAC10 \uC788\uB294 \uC2E4\uB8E8\uC5E3\uACFC \uD3EC\uCF13 \uD50C\uB7A9 \uB514\uD14C\uC77C\uC774 \uD2B9\uC9D5\uC785\uB2C8\uB2E4. \uB450 \uC81C\uD488 \uBAA8\uB450 \uC77C\uCCB4\uD615 \uD6C4\uB4DC\uB97C \uC801\uC6A9\uD55C \uB0A8\uC131 \uB2E4\uC6B4 \uC790\uCF13\uC785\uB2C8\uB2E4"
            }
        }

    ]
}

